    use UsesMarketDataMariaDb;
    private $dirs=[];
    protected function setUp(): void {parent::setUp();$this->bootMarketDataMariaDb();}
    protected function tearDown(): void {foreach($this->dirs as $d){foreach(glob($d.'/*') as $p)if(is_file($p))unlink($p);if(is_dir($d))rmdir($d);}Carbon::setTestNow();$this->tearDownMarketDataMariaDb();parent::tearDown();}
    private function export($id,$name): array {$d=sys_get_temp_dir().'/b19_real_run_'.uniqid();$this->dirs[]=$d;$sourceRun=DB::table('eod_runs')->where('run_id',$id)->first();$inputs=['run'=>$sourceRun,'events'=>DB::table('eod_run_events')->where('run_id',$id)->orderBy('event_id')->get()->all(),'publication'=>DB::table('eod_publications')->where('publication_id',$sourceRun->publication_id)->first(),'lineage'=>DB::table('md_publication_lineage_bindings')->where('publication_id',$sourceRun->publication_id)->first(),'config_snapshot'=>DB::table('md_config_snapshots')->where('config_snapshot_id',$sourceRun->config_snapshot_id)->first(),'observations'=>DB::table('md_source_observations')->where('run_id',$id)->get()->all()];app(MarketDataEvidenceExportService::class)->exportRunEvidence($id,$d);$this->assertSame(json_encode($sourceRun),json_encode(DB::table('eod_runs')->where('run_id',$id)->first()));$this->assertSame(json_encode($inputs['events']),json_encode(DB::table('eod_run_events')->where('run_id',$id)->orderBy('event_id')->get()->all()));$p=json_decode(file_get_contents($d.'/evidence_pack.json'),true);if(getenv('B19_COMPLETION_ARTIFACT_DIR')){$to=getenv('B19_COMPLETION_ARTIFACT_DIR').'/'.$name;if(!is_dir($to))mkdir($to,0775,true);foreach(glob($d.'/*') as $f)if(is_file($f))copy($f,$to.'/'.basename($f));file_put_contents($to.'/authoritative_inputs_before_export.json',json_encode($inputs,JSON_PRETTY_PRINT));file_put_contents($to.'/primary_run.json',json_encode(DB::table('eod_runs')->where('run_id',$id)->first(),JSON_PRETTY_PRINT));file_put_contents($to.'/primary_event_trail.json',json_encode(DB::table('eod_run_events')->where('run_id',$id)->orderBy('event_id')->get()->all(),JSON_PRETTY_PRINT));}return [$p,$d];}
    private function assertRunPack(array $p,$id,$status,$date): void {
        $s=$p['run_summary'];$this->assertSame($id,$s['run_id']);$this->assertSame($date,$s['trade_date_requested']);$this->assertSame($status,$s['terminal_status']);$this->assertSame($s['coverage'],$p['coverage_context']);$this->assertSame($id,$p['run_event_summary']['run_id']);
        $trail=DB::table('eod_run_events')->where('run_id',$id)->get()->all();$stages=[];$reasons=[];foreach($trail as $event){$stages[$event->stage]=($stages[$event->stage]??0)+1;if($event->reason_code!==null&&$event->reason_code!=='')$reasons[$event->reason_code]=($reasons[$event->reason_code]??0)+1;}ksort($stages);ksort($reasons);$this->assertSame($stages,$p['run_event_summary']['stage_counts']);$this->assertSame($reasons,$p['run_event_summary']['reason_code_counts']);$this->assertGreaterThanOrEqual(3,count($trail));
        foreach(['coverage_gate_state','coverage_ratio','coverage_min_threshold','expected_bar_count','available_bar_count','missing_bar_count','coverage_reason_code'] as $f)$this->assertArrayHasKey($f,$p['coverage_context']);if($status==='SUCCESS')foreach(['coverage_gate_state'=>'PASS','coverage_ratio'=>1,'coverage_min_threshold'=>0.98,'expected_bar_count'=>1,'available_bar_count'=>1,'missing_bar_count'=>0,'coverage_reason_code'=>'COVERAGE_THRESHOLD_MET'] as $key=>$value)$this->assertSame($value,$p['coverage_context'][$key]);
        if($status==='SUCCESS'){$this->assertSame('READABLE',$s['publishability_state']);$this->assertSame('SEALED',$p['publication_manifest']['seal_state']);}else{$this->assertSame('NOT_READABLE',$s['publishability_state']);$this->assertSame('ADMITTED_INCOMPLETE',$p['evidence_admission']['evidence_admission_state']);$this->assertFalse($p['pointer_context']['pointer_switch_allowed']);}
    }
