        $frozenReasons=json_decode(file_get_contents($pkg.'/inputs/frozen_reason_registry.json'),true)['entries'];DB::table('eod_reason_codes')->delete();foreach(array_chunk($frozenReasons,100) as $chunk)DB::table('eod_reason_codes')->insert($chunk);
        $responseBody=$body;$mode='normal';$calls=[];$sequence=0;
        $transport=function($url,$context=[])use(&$mode,&$calls,&$sequence,&$responseBody){$sequence++;$status=$mode==='outage'?504:($mode==='auth_error'?401:($mode==='retry'&&$sequence===1?504:200));$calls[]=['url'=>$url,'context'=>$context,'status'=>$status];if($mode==='retry'&&$sequence===1)Carbon::setTestNow('2026-03-25 10:31:00');return ['status'=>$status,'body'=>$status===200?$responseBody:'gateway timeout','headers'=>['Content-Type: application/json']];};
