        foreach(['bars_batch_hash'=>'bars','indicators_batch_hash'=>'indicators','eligibility_batch_hash'=>'eligibility'] as $f=>$member)$this->assertSame($oracle['payload']['artifacts'][$member],$p['publication_manifest'][$f]);
        foreach(['canonicalization_version','formula_version','config_registry_revision','read_model_version','price_product_code','price_product_version'] as $f)$this->assertSame($oracle['payload'][$f],$p['publication_manifest'][$f]);
